const items = $input.all();

function trim(v) {
  return String(v ?? '').trim();
}

function normalizePhone(v) {
  const raw = trim(v).replace(/[^\d+]/g, '');
  if (!raw) return '';
  const canonical = raw.startsWith('+62') ? `62${raw.slice(3)}` : raw;
  return canonical.startsWith('0') ? `62${canonical.slice(1)}` : canonical;
}

return items.map((item) => {
  // Webhook n8n (v2) membungkus body POST di item.json.body. Fallback ke root.
  const payload = (item.json && item.json.body) ? item.json.body : (item.json || {});
  // Generik: terima `to` (PpdbWhatsappNotifier) ATAU `target` (modul Notifikasi/WaGatewayService).
  const to = normalizePhone(payload.to || payload.target);
  const message = trim(payload.message);

  if (!to) throw new Error('Payload invalid: field "to"/"target" wajib diisi.');
  if (!message) throw new Error('Payload invalid: field "message" wajib diisi.');

  return {
    json: {
      to,
      chatId: `${to}@c.us`,
      message,
      eticket_no: trim(payload.eticket_no) || null,
      student_name: trim(payload.student_name) || null,
      template_code: trim(payload.template_code) || null,
      source: trim(payload.source) || 'ppdb_register',
      received_at: new Date().toISOString()
    }
  };
});

const items = $input.all();

const endpointBase = String($env.N8N_WAHA_BASE_URL || 'http://waha:3000').trim().replace(/\/+$/, '');
const endpoint = `${endpointBase}/api/sendText`;
const token = String($env.N8N_WAHA_API_KEY || '').trim();
const session = String($env.N8N_WAHA_SESSION || 'default').trim() || 'default';

const out = [];
for (const { json } of items) {
  try {
    const response = await this.helpers.httpRequest({
      method: 'POST',
      url: endpoint,
      headers: token ? { 'X-Api-Key': token } : {},
      body: { session, chatId: json.chatId, text: json.message },
      json: true,
      returnFullResponse: true,
    });
    const bodyStr = typeof response.body === 'string' ? response.body : JSON.stringify(response.body);
    out.push({ json: { ...json, sent: true, provider: 'waha', reason: 'sent', gateway_status: response.statusCode, gateway_response: bodyStr ? bodyStr.slice(0, 500) : null } });
  } catch (error) {
    const status = error.statusCode || error.httpCode || 0;
    out.push({ json: { ...json, sent: false, provider: 'waha', reason: status ? `http_${status}` : 'request_error', gateway_status: status, gateway_response: String(error?.message || error || 'unknown_error').slice(0, 500) } });
  }
}

return out;
